/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Boolean obd_can_rx_bat_volt (Obd_Can_Rx_Msg * obd_can_rx_msg)
{
  #define DATA(z) obd_can_rx_msg->data[z]

  #if STATUS_ENGINE_ENABLE == 1
	      
		engine.bat_volt = (((UInt32)(DATA(1)<< 8) | DATA(2) ) / 1000) ;
	  
  #endif

#if DBG_OBD_CAN == 1
  dbg_tx_text("*** obd_can_rx_bat_volt = ");
  dbg_tx_h32(engine.bat_volt);
  dbg_tx_text("\r\n");
#endif

  return TRUE ;

  #undef DATA
}


